from __future__ import annotations

import argparse
import csv
import random
import shutil
from pathlib import Path


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Prepare train/validation image folders and label files from "
            "training_labels.csv generated by output.mode=training_dataset."
        )
    )
    parser.add_argument("--labels", required=True, help="Generated training_labels.csv")
    parser.add_argument("--output-dir", required=True)
    parser.add_argument("--validation-ratio", type=float, default=0.10)
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument(
        "--allow-draft-labels",
        action="store_true",
        help=(
            "Use ocr_draft_label when corrected_label is empty. Disabled by default "
            "because training should normally use human-corrected labels."
        ),
    )
    return parser


def _read_rows(path: Path, allow_draft: bool) -> list[tuple[Path, str]]:
    rows: list[tuple[Path, str]] = []
    with path.open(encoding="utf-8-sig", newline="") as handle:
        for record in csv.DictReader(handle):
            image_path = Path(record.get("image_path", "").strip())
            corrected = record.get("corrected_label", "").strip()
            draft = record.get("ocr_draft_label", "").strip()
            label = corrected or (draft if allow_draft else "")
            if not image_path.exists() or not label:
                continue
            rows.append((image_path, label.replace("\t", " ").replace("\n", " ")))
    return rows


def _write_split(split_name: str, rows: list[tuple[Path, str]], output_root: Path) -> None:
    images_dir = output_root / split_name / "images"
    images_dir.mkdir(parents=True, exist_ok=True)
    csv_path = output_root / split_name / "labels.csv"
    tsv_path = output_root / split_name / "labels.tsv"

    with csv_path.open("w", encoding="utf-8-sig", newline="") as csv_handle, tsv_path.open(
        "w", encoding="utf-8", newline=""
    ) as tsv_handle:
        writer = csv.DictWriter(csv_handle, fieldnames=["filename", "label"])
        writer.writeheader()
        for index, (source, label) in enumerate(rows, start=1):
            destination = images_dir / f"{index:07d}{source.suffix.lower()}"
            shutil.copy2(source, destination)
            relative = destination.relative_to(output_root)
            writer.writerow({"filename": str(relative), "label": label})
            tsv_handle.write(f"{relative}\t{label}\n")


def main() -> int:
    args = build_parser().parse_args()
    labels_path = Path(args.labels)
    output_root = Path(args.output_dir)
    ratio = max(0.0, min(0.90, float(args.validation_ratio)))
    rows = _read_rows(labels_path, args.allow_draft_labels)
    if not rows:
        raise SystemExit(
            "No usable labeled rows were found. Fill corrected_label in the CSV, "
            "or explicitly pass --allow-draft-labels for an initial experiment."
        )

    random.Random(args.seed).shuffle(rows)
    validation_count = int(round(len(rows) * ratio))
    if len(rows) > 1 and ratio > 0:
        validation_count = max(1, min(len(rows) - 1, validation_count))
    validation_rows = rows[:validation_count]
    training_rows = rows[validation_count:]

    _write_split("train", training_rows, output_root)
    _write_split("validation", validation_rows, output_root)
    print(
        {
            "output_dir": str(output_root.resolve()),
            "train_samples": len(training_rows),
            "validation_samples": len(validation_rows),
        }
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
